SELECT COUNT(*) FROM data_element_business_record
WHERE batch_id = #{batchId}
  AND data_type = #{dataType}

SELECT
    r.data_subtype,
    COUNT(*) AS record_count,
    MAX(r.created_at) AS last_upload_time,
    (SELECT b.uploader FROM data_element_upload_batch b
     WHERE b.id = (
         SELECT r2.batch_id FROM data_element_business_record r2
         WHERE r2.data_type = #{dataType}
           AND r2.data_subtype = r.data_subtype
         ORDER BY r2.created_at DESC LIMIT 1
     )
    ) AS last_uploader,
    (SELECT b.original_file_name FROM data_element_upload_batch b
     WHERE b.id = (
         SELECT r3.batch_id FROM data_element_business_record r3
         WHERE r3.data_type = #{dataType}
           AND r3.data_subtype = r.data_subtype
         ORDER BY r3.created_at DESC LIMIT 1
     )
    ) AS last_file_name
FROM data_element_business_record r
WHERE r.data_type = #{dataType}
GROUP BY r.data_subtype

SELECT * FROM data_element_business_record
WHERE data_type = #{dataType}
ORDER BY data_subtype, created_at
